@wd.page core.word text=page text=sheet text=paper means=page
@h.page std.schema.honours world=drawing act=make of=page
@wd.things core.word text=thing text=things text=items means=part
# The door (reviewer 2026-11-15 16:40): the wholes whose requests this world plans through the library. Read by src/dialog/request.mjs doorWholes.
@door psys2.door world=drawing whole=pond whole=forest whole=garden
# The session timeline (reviewer 2026-11-15 19:05): the world's own undo and redo, the operations the door calls for the acts undo / redo of k.actions (src/dialog/request.mjs actOperation).
@op.undo psys2.op world=drawing act=undo op=undoStep
@op.redo psys2.op world=drawing act=redo op=redoStep
# A whole the world makes with an operation of its own, not by a plan of parts: a new page is the board's fresh sheet (the old one stays for undo).
@op.page psys2.op world=drawing act=make of=page op=newPage
# Acts on the things that are there (spec 28 section 12): what each honours, and the one operation of the world that carries them out (the door resolves the things and the roles).
@k.picture std.schema.kind of=picture world=drawing acts=make acts=remove
@h.place std.schema.honours world=drawing act=place on=place of=thing of=picture
@h.change std.schema.honours world=drawing act=change on=attribute on=size of=thing of=picture
@h.remove std.schema.honours world=drawing act=remove of=thing of=picture
@wd.colour core.word text=color text=colour means=colour
# TOOL BINDING (spec 28 section 12; reviewer 2026-11-15 20:45; sopworld 0.152.1 std.tool): the board's primitives with their typed parameters (std.tool.op / std.tool.param), the act of a
# plan step bound to one primitive with its arguments' sources (std.tool.bind / std.tool.arg), the preconditions (needs=) and the effect on the view (makes / removes / changes).
# The library's runPlan fills the arguments (said, revised, the plan's values, the expectations below), translates a value the parameter does not take by knowledge (tiny -> small by
# k.expect.scale; a water lily -> a flower by std.schema.drawn), checks, calls the primitive (worlds/art.draw/engine.mjs: no words, no defaults) and reads the view before and after.
@tool core.use world=std.tool
# A scene (a pond, a forest, a garden: a picture) is a whole the library plans with its parts (k.expect.make / k.expect.part of the catalog, by join; the structure operators
# keep it when a count is revised): the whole is a scene of the board (startScene), each part is drawn in it (addThings whole<-step.in), and an act on the scene is an act on its things.
@op.scene std.tool.op name=startScene world=drawing param=kind param=place effect=makes doc="a scene: the whole its things are drawn in (they stand together)"
@pa.scene.place std.tool.param op=startScene name=place kind=atom
@v.scene.corner std.tool.value op=startScene param=place value=corner as=bottom_left
@b.scene std.tool.bind world=drawing act=make of=pond of=forest of=garden op=startScene arg=kind<-step.kind arg=place<-step.place makes=thing
@op.add std.tool.op name=addThings world=drawing param=kind param=n param=size param=colour param=place param=anchor param=whole effect=makes doc="draw n things of a kind of the board"
@pa.add.place std.tool.param op=addThings name=place kind=atom
@v.add.corner std.tool.value op=addThings param=place value=corner as=bottom_left
@v.add.land std.tool.value op=addThings param=place value=land as=ground
@pa.add.kind std.tool.param op=addThings name=kind type=thing required=true accepts=house accepts=tree accepts=sun accepts=cloud accepts=flower accepts=cat accepts=dog accepts=fish accepts=bird accepts=boat accepts=mountain accepts=hill accepts=lake accepts=river accepts=butterfly
@pa.add.n std.tool.param op=addThings name=n kind=integer min=1 max=12 default=1
@pa.add.size std.tool.param op=addThings name=size type=k.expect.scale by=step accepts=small accepts=default accepts=big
@b.add std.tool.bind world=drawing act=make of=thing op=addThings makes=thing
@a.add.kind std.tool.arg bind=$b.add param=kind from=step.kind
@a.add.n std.tool.arg bind=$b.add param=n from=step.count
@a.add.size std.tool.arg bind=$b.add param=size from=step.size
@a.add.colour std.tool.arg bind=$b.add param=colour from=step.colour
@a.add.place std.tool.arg bind=$b.add param=place from=step.place
@a.add.anchor std.tool.arg bind=$b.add param=anchor from=custom.thingAt
@a.add.whole std.tool.arg bind=$b.add param=whole from=step.in
@op.sky std.tool.op name=paintSky world=drawing param=colour effect=makes doc="the sky band behind everything, in a colour"
@b.sky std.tool.bind world=drawing act=make of=sky op=paintSky arg=colour<-step.colour makes=thing
@op.remove std.tool.op name=removeThings world=drawing param=ids effect=removes
@b.remove std.tool.bind world=drawing act=remove of=thing op=removeThings arg=ids<-step.things needs=exists(ids) removes=ids
@b.remove.scene std.tool.bind world=drawing act=remove of=pond of=forest of=garden op=removeThings arg=ids<-step.things
@op.move std.tool.op name=moveThings world=drawing param=ids param=place param=anchor param=relation effect=changes
@pa.move.place std.tool.param op=moveThings name=place kind=atom
@v.move.corner std.tool.value op=moveThings param=place value=corner as=bottom_left
@v.move.water std.tool.value op=moveThings param=place value=water as=sea
@v.move.sea std.tool.value op=moveThings param=place value=ocean as=sea
@v.move.land std.tool.value op=moveThings param=place value=land as=ground
@v.move.lawn std.tool.value op=moveThings param=place value=lawn as=grass
@v.move.beach std.tool.value op=moveThings param=place value=beach as=sand
@c.thingAt std.tool.custom name=thingAt world=drawing kind=search in=place out=anchor doc="the newest thing of the kind a place names (next to it)"
@pa.move.relation std.tool.param op=moveThings name=relation kind=atom
@v.move.next std.tool.value op=moveThings param=relation value="next to" as=next
@v.move.beside std.tool.value op=moveThings param=relation value=beside as=next
@v.move.near std.tool.value op=moveThings param=relation value=near as=next
@v.move.by std.tool.value op=moveThings param=relation value=by as=next
@v.move.front std.tool.value op=moveThings param=relation value="in front of" as=front
@v.move.under std.tool.value op=moveThings param=relation value=under as=below
@v.move.underneath std.tool.value op=moveThings param=relation value=underneath as=below
@v.move.beneath std.tool.value op=moveThings param=relation value=beneath as=below
@v.move.over std.tool.value op=moveThings param=relation value=over as=above
@v.move.inside std.tool.value op=moveThings param=relation value=inside as=in
@v.move.into std.tool.value op=moveThings param=relation value=into as=in
@v.move.onto std.tool.value op=moveThings param=relation value=onto as=on
@v.move.left std.tool.value op=moveThings param=relation value="left of" as=leftof
@v.move.right std.tool.value op=moveThings param=relation value="right of" as=rightof
@b.move std.tool.bind world=drawing act=place of=thing op=moveThings arg=ids<-step.things arg=place<-step.place arg=anchor<-step.region arg=relation<-step.relation needs=exists(ids)
@b.move.scene std.tool.bind world=drawing act=place of=pond of=forest of=garden op=moveThings arg=ids<-step.things arg=place<-step.place arg=anchor<-step.region arg=relation<-step.relation needs=exists(ids)
@op.set std.tool.op name=setThings world=drawing param=ids param=colour param=size effect=changes
@pa.set.size std.tool.param op=setThings name=size type=k.expect.scale by=step accepts=small accepts=default accepts=big
@b.set std.tool.bind world=drawing act=change of=thing op=setThings arg=ids<-step.things arg=colour<-step.colour arg=size<-step.size needs=exists(ids)
@b.set.scene std.tool.bind world=drawing act=change of=pond of=forest of=garden op=setThings arg=ids<-step.things arg=colour<-step.colour arg=size<-step.size needs=exists(ids)
# What the acts on the things that are there honour (the library's reference step resolves the things by kind, the values said before the kind, "it" / "them")
@h.remove.kind std.schema.honours world=drawing act=remove on=kind on=count on=attribute of=thing
@h.change.kind std.schema.honours world=drawing act=change on=kind on=attribute on=size of=thing
@h.place.kind std.schema.honours world=drawing act=place on=kind on=place of=thing
# Defaults are expectations (k.expect.value ... when.), chosen by the library and said in `assumed`
@x.small.place k.expect.value of=thing on=place value=corner when.size=small about="a small thing goes in a corner"
@x.sky.colour k.expect.value of=sky on=colour value=blue about="the sky is blue unless said"
# KINDS BY JOIN (sopworld 0.160; reviewer 05:05 slice 2): every object of the catalog (k.objects.object, with its stand-ins: a villa is drawn as the house) and every kind of person
# (k.people.kind) is a kind of this world for its acts; the board draws one through the catalog's lazy loader (a joined kind is drawn by its catalog object, or its stand-in's).
# A joined kind is never planned as a whole by the catalog's k.expect.make: the wholes the board draws are its declared kinds (pond, forest, garden above: std.schema.kind, the forest with its own k.expect.make; the parts of pond and garden are the catalog's).
@kinds.objects std.schema.kinds world=drawing from=k.objects.object key=name acts=make acts=remove acts=place acts=change
@kinds.people std.schema.kinds world=drawing from=k.people.kind key=name acts=make acts=remove acts=place acts=change
@h.make.joined std.schema.honours world=drawing act=make on=kind on=count on=size on=place on=attribute on=with of=k.objects.object of=k.people.kind
@h.remove.joined std.schema.honours world=drawing act=remove on=kind on=count on=attribute of=k.objects.object of=k.people.kind
@h.change.joined std.schema.honours world=drawing act=change on=kind on=attribute on=size of=k.objects.object of=k.people.kind
@h.place.joined std.schema.honours world=drawing act=place on=kind on=place of=k.objects.object of=k.people.kind
# a joined kind is drawn by addJoined: the same primitive as addThings, whose kind parameter takes every declared kind (no accepts list: the board looks the kind up in the catalog)
@op.addj std.tool.op name=addJoined world=drawing param=kind param=n param=size param=colour param=place param=anchor param=whole effect=makes doc="draw n things of a kind the world takes from the catalog"
@pa.addj.kind std.tool.param op=addJoined name=kind type=kind required=true
@pa.addj.n std.tool.param op=addJoined name=n kind=integer min=1 max=12 default=1
@pa.addj.size std.tool.param op=addJoined name=size type=k.expect.scale by=step accepts=small accepts=default accepts=big
@pa.addj.place std.tool.param op=addJoined name=place kind=atom
@b.addj std.tool.bind world=drawing act=make of=k.objects.object of=k.people.kind op=addJoined arg=kind<-step.kind arg=n<-step.count arg=size<-step.size arg=colour<-step.colour arg=place<-step.place arg=anchor<-custom.thingAt arg=whole<-step.in makes=thing
@b.remove.joined std.tool.bind world=drawing act=remove of=k.objects.object of=k.people.kind op=removeThings arg=ids<-step.things needs=exists(ids) removes=ids
@b.move.joined std.tool.bind world=drawing act=place of=k.objects.object of=k.people.kind op=moveThings arg=ids<-step.things arg=place<-step.place arg=anchor<-step.region arg=relation<-step.relation needs=exists(ids)
@b.set.joined std.tool.bind world=drawing act=change of=k.objects.object of=k.people.kind op=setThings arg=ids<-step.things arg=colour<-step.colour arg=size<-step.size needs=exists(ids)
# The board's own wholes with the parts it draws by itself (reviewer 05:05 slice 2: what the board draws as wholes is its own k.expect.make): the catalog's pond and garden less the
# parts that are only joined kinds (frog, stone, grass, fence, bench: drawn when asked, "a pond with a frog", never needed by a scene, so a scene never waits for the catalog)
@e.pond k.expect.make thing=pond made_in=drawing unit=part min=4 max=9 typical=6 kinds_min=3 kinds_max=4 layout=free
@e.pond.water k.expect.part of=pond part=water group=water min=1 max=1 typical=1 needed=yes
@e.pond.lily k.expect.part of=pond part="water lily" group=plant min=2 max=5 typical=3
