@e.garden k.expect.make thing=garden made_in=drawing unit=part min=5 max=14 typical=9 kinds_min=3 kinds_max=5 layout=free
@e.garden.flower k.expect.part of=garden part=flower group=plant min=3 max=10 typical=5 needed=yes
@e.garden.tree k.expect.part of=garden part=tree group=plant min=0 max=2 typical=1
